"""Synthetic design fixture generated by existing Plan analysis; no IO to application data."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path[:0] = [str(ROOT / 'apps/plan-api'), str(ROOT / 'packages/fincore/src')]
from plan_api.schemas import Checkup, CheckupData, Member, IncomeRow, ExpenseRow, LiabilityRow, SavingsRow, Range
from plan_api.analysis.report import build_report


def sample(month, reserve, card, loan):
    return Checkup(id=f'demo-{month}', entry_question='overview', as_of=month, status='completed', completed_at=f'{month}-07T10:30:00+03:00',
        members=[Member(id='a', label='Я'), Member(id='b', label='Партнёр')],
        data=CheckupData(
            incomes=[IncomeRow(member_id='a', amount=Range(min=110000, max=130000)), IncomeRow(member_id='b', amount=Range.exact(60000))],
            expenses=[ExpenseRow(category_key='life', title='Жизнь семьи', amount=Range(min=100000, max=110000))],
            liabilities=[LiabilityRow(id='card', title='Кредитная карта', kind='card', balance=card, annual_rate=24, monthly_payment=10000),
                         LiabilityRow(id='loan', title='Потребительский кредит', balance=loan, annual_rate=12, monthly_payment=20000)],
            savings=[SavingsRow(amount=Range.exact(reserve), is_safety_fund=True)]))


current = build_report(sample('2026-11', 270000, 60000, 240000))
previous = build_report(sample('2026-10', 225000, 68627.45, 257425.74))
first = build_report(sample('2026-09', 180000, 77085.74, 274678.95))
payload = dict(current=current, history=[first, previous, current],
    origin='Existing plan_api.analysis.report.build_report / synthetic inputs only',
    assumptions=dict(income=[170000,190000], living_expenses=[100000,110000], debt_payment=30000,
                     debt_total=300000, reserve=270000, rates='Synthetic: card 24%, consumer loan 12%. Not market offers.'))
Path(__file__).with_name('fixture.js').write_text('window.ATLAS_FIXTURE = ' + json.dumps(payload, ensure_ascii=False, allow_nan=False, indent=2) + ';\n', encoding='utf-8')
print(json.dumps({key: current[key] for key in ['free_cashflow', 'net_worth', 'debt_strategy']}, ensure_ascii=False, indent=2))
